#include <cstdio>
#include <algorithm>
const int Maxn=500;
int n,m,Mod;
int C[Maxn+5][Maxn+5];

void initialize(){
    C[0][0]=1;
    for(int i=1;i<=Maxn;i++){
        C[i][0]=C[i][i]=1;
        for(int j=1;j<i;j++){
            C[i][j]=(C[i-1][j]+C[i-1][j-1])%Mod;
        }
    }
}

int minimum(int a,int b){ return a<b?a:b; }
int absolute(int a){ return a<0?-a:a; }

int f1[Maxn+5],f2[Maxn+5];
int f3[Maxn+5][Maxn+5],f4[Maxn+5][Maxn+5];

int main(){
    scanf("%d%d%d",&n,&m,&Mod);
    initialize();

    f1[0]=1;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=i;j++){
            f1[i]=(f1[i]+(long long)f1[i-j]*f1[j-1]%Mod*C[i-1][j-1])%Mod;
        }
        f1[i]=(long long)f1[i]*(i+1)%Mod;
    }

    for(int i=1;i<=n;i++){
        for(int j=1;j<=i;j++){
            int total=0;
            for(int k=1;k<=i;k++){
                total+=absolute(k-j);
            }
            f2[i]=(f2[i]+((long long)j*(j-1)/2+(long long)(i-j)*(i-j+1)/2)%Mod*f1[j-1]%Mod*f1[i-j]%Mod*C[i-1][j-1])%Mod;
            f2[i]=(f2[i]+(long long)f2[j-1]*f1[i-j]%Mod*C[i-1][j-1]*(i+1))%Mod;
            f2[i]=(f2[i]+(long long)f2[i-j]*f1[j-1]%Mod*C[i-1][j-1]*(i+1))%Mod;
        }
    }

    f3[0][0]=1;
    for(int i=1;i<=n;i++){
        for(int j=0;j<=minimum(i,m);j++){
            f3[i][j]=f3[i-1][j];
            for(int k=1;k<=j;k++){
                if(i-1-k>=0){
                    f3[i][j]=(f3[i][j]+(long long)f1[k]*f3[i-1-k][j-k]%Mod*C[j][k])%Mod;
                } else {
                    f3[i][j]=(f3[i][j]+(long long)f1[k]*C[j][k])%Mod;
                }
            }
        }
    }

    for(int i=1;i<=n;i++){
        for(int j=0;j<=minimum(i,m);j++){
            f4[i][j]=f4[i-1][j];
            for(int k=1;k<=j;k++){
                if(i-1-k>=0){
                    f4[i][j]=(f4[i][j]+(long long)(f3[i-1-k][j-k]*f2[k]+f4[i-1-k][j-k]*f1[k])%Mod*C[j][k])%Mod;
                } else {
                    f4[i][j]=(f4[i][j]+(long long)f2[k]*C[j][k])%Mod;
                }
            }
        }
    }

    printf("%d\n",f4[n][m]);
    return 0;
}
